export { searchProducts, searchCategories, searchAll } from './search-helpers';

// 鑾峰彇浜у搧鏍囬锛堟牴鎹瑷€锛?
// 2026-07-14 P0 fix: name 瀛楁缁撴瀯鏄?"鐭悕 | 鐭悕 / 绫荤洰闀垮熬"锛屽 "闃叉按璨肩礄 | 闃叉按璨肩礄 / 鐣板舰璨肩礄"
// 涔嬪墠鐩存帴 return product.name 浼氳 H1 / breadcrumb / image alt 鍑虹幇 3x 閲嶅
// 淇硶: 鎸?'|' split 鍙?[0] 鐭悕锛堝幓閲?+ 骞插噣锛夛紝褰卞搷 9 涓敤娉曪紙page.tsx / ProductCard / RelatedProducts / HotProducts / QuoteCalculator / guide / not-found / blog / BlogContent锛?
export function getProductTitle(product: Product, locale: string): string {
  let raw: string;
  switch (locale) {
    case 'zh-hk':
      raw = product.name;
      break;
    case 'en':
      raw = product.nameEn;
      break;
    case 'ja':
      raw = product.nameJa;
      break;
    default:
      raw = product.name;
  }
  // 鐭悕鍖? 鎸?'|' split 鍙?[0]锛堝鐞?"A | B" 鎴?"A | B / C" 涓ょ pattern锛?
  // 娉ㄦ剰: 鎷嗗畬鍐嶅仛 trim 閬垮厤 "A | B" 鈫?" A" 娈嬬暀
  const short = raw.split('|')[0].trim();
  return short || raw;  // 鏋佺 fallback锛堢┖ short 鏃跺洖閫€鍘?name锛?
}

// V8 浼樺寲鐗?display title (SSoT for ALL display contexts: 棣栭〉/鎼滅储/RelatedProducts/QuoteCalculator)
// 2026-07-15 淇椤电煭鏍囬 root cause: 4 caller 涔嬪墠鐩存帴鐢?getProductTitle 杩?V6 鐭悕
//   - HotProducts.tsx (棣栭〉)
//   - src/components/ProductCard.tsx (search page, capital P)
//   - RelatedProducts.tsx (PDP 鎺ㄨ崘)
//   - QuoteCalculator.tsx (鎶ヤ环璁＄畻鍣?
//
// 淇硶: 鏂板姞姝ゅ嚱鏁版案杩滆繑 V8 (璧?h1-builder for 3 locale), 4 caller 鍒囨崲鍗冲彲.
// page.tsx (PDP) 浠嶇敤 getProductTitle (V6) 鍥犱负 h1-builder input 闇€瑕佺煭鍚? 涓嶈兘 V8 鈫?V8 builder.
export function getProductDisplayTitle(product: Product, locale: string): string {
  const baseTitle = getProductTitle(product, locale); // V6 鐭悕
  switch (locale) {
    case 'en':
      return buildProductH1En(baseTitle, product.category_slug);
    case 'ja':
      return buildProductH1Ja(baseTitle, product.category_slug);
    case 'zh-hk':
    default: {
      // 浼樺厛鐢?title_zh 瀛楁 (Cline V8 鏈熼棿琛ョ殑鐭悕), 娌℃湁鍐?fallback 鍒?getProductTitle
      const shortBase = (product as any).title_zh || baseTitle;
      const cat = categories.find(c => c.slug === product.category);
      return buildProductH1ZhHk(
        shortBase,
        (cat as any)?.name_zh || (cat as any)?.name || product.category,
        product.category,
        product.slug
      );
    }
  }
}

// 鑾峰彇浜у搧鎻忚堪锛堟牴鎹瑷€锛?
